    let answers_for_columns = [
        ("cpu", 88.257434),
        ("mem", 3032375296.),
        ("virtual", 102579965952.),
    ];
    for (column_name, expected_value) in answers_for_columns {
        let actual = nu!(
            cwd: "tests/fixtures/formats/",
